# -*- coding: utf-8 -*-
"""개념서 Ⅲ-A 한글 맞춤법: 원리와 소리 (3개 절) · Ⅲ-B 한글 맞춤법: 형태 (5개 절)"""
from chtml import *

SECS_A = []
SECS_B = []


def seca(title, types, *parts):
    SECS_A.append(dict(title=title, types=types, html=SEC(*parts)))


def secb(title, types, *parts):
    SECS_B.append(dict(title=title, types=types, html=SEC(*parts)))


